/* A static newspaper broadside: existing typefaces, normal flow, no motion runtime. */
.times-editorial{--times-paper:#f3eee6;--times-ink:#541919;margin-top:clamp(88px,11.5vw,210px);padding-top:clamp(44px,5.5vw,96px);border-top:1px solid #f3eee632;color:var(--cream,#f3eee6)}
.times-editorial-composition{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(42px,5.8vw,108px);align-items:stretch}
.times-editorial-paper{display:flex;flex-direction:column;min-width:0;margin:0;padding:clamp(25px,2.7vw,49px);background:var(--times-paper);color:var(--times-ink);box-shadow:0 10px 36px #0000001a}
.times-editorial-paper-topline{display:flex;justify-content:space-between;align-items:baseline;gap:16px;margin-bottom:clamp(22px,2.2vw,40px);font-size:8px;line-height:1.5;letter-spacing:.08em;text-transform:uppercase}
.times-editorial-paper-topline>span:last-child{text-align:right}
.times-editorial-masthead{display:block;width:100%;height:auto}
.times-editorial-paper-rule{border-top:3px double #5419198f;margin-top:clamp(19px,1.8vw,34px)}
.times-editorial-paper-lead{margin:clamp(34px,3.7vw,68px) 0;font-family:'Innecta Serif',Georgia,serif;font-size:clamp(30px,3.05vw,56px);font-weight:400;line-height:1.13;letter-spacing:-.055em}
.times-editorial-paper-lead>span{display:block}
.times-editorial-paper-lead>span+span{margin-top:.25em}
.times-editorial-paper-columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px;margin-top:auto;padding-top:19px;border-top:1px solid #54191952;font-family:'Innecta Serif',Georgia,serif;font-size:clamp(12px,1.1vw,19px);line-height:1.45;letter-spacing:-.025em}
.times-editorial-paper-columns>p+p{padding-left:20px;border-left:1px solid #54191952}
.times-editorial-paper-caption{margin-top:28px;padding-top:13px;border-top:1px solid #54191952;font-size:9px;line-height:1.5;letter-spacing:.015em;color:#6c4b45}
.times-editorial-copy{display:flex;flex-direction:column;align-items:flex-start;min-width:0;padding:clamp(8px,1.7vw,30px) 0}
.times-editorial-eyebrow{margin-bottom:clamp(22px,2.1vw,38px);font-size:10px;line-height:1.5;font-weight:400;letter-spacing:.13em;text-transform:uppercase;color:#d9bac4}
.times-editorial-copy h2{font-size:clamp(35px,3.65vw,66px);font-weight:400;letter-spacing:-.055em;line-height:1.09}
.times-editorial-copy h2>span,.times-editorial-copy h2>em{display:block}
.times-editorial-copy h2>em{margin-top:.13em;font-weight:400;font-style:italic;color:#d9adb9}
.times-editorial-description{max-width:42ch;margin-top:clamp(24px,2.3vw,40px);font-size:clamp(14px,1.08vw,18px);line-height:1.7;color:#d6c8ce}
.times-editorial-desk{width:100%;margin-top:clamp(28px,3vw,54px);padding-top:18px;border-top:1px solid #f3eee632}
.times-editorial-desk-label{font-size:9px;line-height:1.6;letter-spacing:.07em;text-transform:uppercase;color:#bba8b1}
.times-editorial-sections{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px 20px;margin:16px 0 0;padding:0;list-style:none;font-size:clamp(12px,.94vw,16px);line-height:1.45;color:#e7d8de}
.times-editorial-action{margin-top:clamp(30px,3vw,54px)}
.times-editorial-button{display:inline-flex;align-items:center;justify-content:space-between;gap:34px;min-height:56px;min-width:205px;padding:16px 22px;border:1px solid #f3eee6;border-radius:999px;background:var(--times-paper);color:var(--times-ink);font-size:15px;line-height:1.3;transition:background-color .2s ease,color .2s ease}
.times-editorial-button svg{width:24px;height:24px;flex:none}
.times-editorial-button:hover{background:#e4cbd0;color:#411111}
.times-editorial-button:focus-visible{outline:2px solid #f3eee6;outline-offset:6px}
.times-editorial-pending{display:inline-flex;align-items:center;min-height:44px;padding:9px 0;font-size:17px;line-height:1.3;letter-spacing:-.02em;color:#f3eee6}
.times-editorial-pending:before{content:'';width:5px;height:5px;margin-right:12px;border-radius:50%;background:#d9adb9}
.times-editorial-access{margin-top:11px;font-size:11px;line-height:1.6;color:#bba8b1}
@media(max-width:1023px){.times-editorial{margin-top:88px;padding-top:44px}.times-editorial-composition{grid-template-columns:1fr;gap:38px}.times-editorial-paper{max-width:560px;width:100%;padding:clamp(24px,5.5vw,40px)}.times-editorial-paper-topline{margin-bottom:24px;font-size:8px}.times-editorial-paper-rule{margin-top:22px}.times-editorial-paper-lead{font-size:clamp(32px,7.5vw,48px);line-height:1.12;margin:40px 0}.times-editorial-paper-columns{font-size:14px;padding-top:18px;gap:20px}.times-editorial-paper-caption{margin-top:26px;font-size:9px}.times-editorial-copy{padding:0;max-width:560px}.times-editorial-eyebrow{font-size:9px;margin-bottom:20px}.times-editorial-copy h2{font-size:clamp(33px,7.7vw,54px);line-height:1.1}.times-editorial-description{font-size:14px;margin-top:24px;max-width:43ch}.times-editorial-desk{margin-top:28px}.times-editorial-sections{font-size:13px;gap:10px 22px}.times-editorial-action{margin-top:28px}.times-editorial-button{min-width:220px;min-height:56px}.times-editorial-access{font-size:11px}}
@media(prefers-reduced-motion:reduce){.times-editorial-button{transition:none}}
